-- Signal Groups starter templates (public, read-only). Run after 2026-11-04_signal_groups.sql.
-- Safe to run more than once: an unchanged starter adds no new version; a changed one adds the next version.
-- Generated from signal_groups/starters/*.json (tests/test_signal_groups_db.py checks they match).
-- 8 Nov 2026: "Trend Confirmation" is renamed "Trend agreement" (a new version; the name below follows it).
-- 5 Nov 2026: adds starter:trend, starter:stretch and starter:flow (the dashboard's readings as Groups). Re-runnable.
select public.analysis_seed_starter('starter:trend-confirmation', $json${"conditions":[{"key":"bullish_confirmed","kind":"confirmation","label":"Uptrend with 4-hour momentum agreeing (same price source; not independent confirmation)","rule":{"all":[{"score":{"gte":0.5}},{"eq":"up","member":"momentum_4h"}]}},{"key":"bearish_confirmed","kind":"confirmation","label":"Downtrend with 4-hour momentum agreeing (same price source; not independent confirmation)","rule":{"all":[{"score":{"lte":-0.5}},{"eq":"down","member":"momentum_4h"}]}},{"key":"ranging_veto","kind":"veto","label":"Daily regime is ranging: trend readings are not meaningful","rule":{"eq":"ranging","field":"state","member":"regime_1d"}}],"lineage_version":2,"members":[{"category":"trend","key":"trend_1d","label":"Daily trend","ref":{"id":"trend.direction","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"kind":"map","map":{"down":-1,"mixed":0,"up":1},"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"trend","key":"trend_4h","label":"4-hour trend","ref":{"id":"trend.direction","params":{},"timeframe":"4h","version":1},"role":"score","transform":{"kind":"map","map":{"down":-1,"mixed":0,"up":1},"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"structure","key":"structure_1d","label":"Daily swing structure","ref":{"id":"structure.swings","params":{"count":6,"left":5,"right":5},"timeframe":"1D","version":1},"role":"score","transform":{"field":"structure","kind":"map","map":{"down":-1,"mixed":0,"unknown":null,"up":1},"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"momentum","key":"momentum_4h","label":"4-hour momentum","ref":{"id":"momentum.direction","params":{},"timeframe":"4h","version":1},"role":"condition"},{"category":"regime","key":"regime_1d","label":"Daily regime","ref":{"id":"regime.observation","params":{"confirm":3,"window":250},"timeframe":"1D","version":1},"role":"condition"}],"name":"Trend agreement","notes":"Every member derives from price, so agreement shows consistency between views of one source, not independent confirmation. Momentum repeats trend (about 80% agreement on development data) and is therefore a condition, not a second vote. Thresholds (0.5, 2/3) are conventions, not tuned on returns.","question":"Is there a trend on the higher timeframes, and does the lower timeframe support it?","schema":"angstrom.group/1","score":{"meaning":"Direction of price-trend evidence: +1 when every scoring member points up, -1 when every one points down. Not a forecast.","method":"weighted_mean","min_coverage":{"den":3,"num":2},"range":[-1,1]}}$json$::jsonb);
select public.analysis_seed_starter('starter:reversal-evidence', $json${"conditions":[{"key":"bullish_reversal_setup","kind":"confirmation","label":"Bullish reversal: at least two corroborating price observations (not independent: all derive from price)","rule":{"count_at_least":2,"of":[{"any":[{"events":{"type_in":["regular_bullish"]},"member":"rsi_div_4h"},{"events":{"type_in":["regular_bullish"]},"member":"macd_div_4h"}]},{"events":{"direction":"bullish","kind_in":["CHoCH"],"within_candles":20},"member":"breaks_4h"},{"field":"support.0.distance_atr","lte":1.0,"member":"zones_1d"}]}},{"key":"bearish_reversal_setup","kind":"confirmation","label":"Bearish reversal: at least two corroborating price observations (not independent: all derive from price)","rule":{"count_at_least":2,"of":[{"any":[{"events":{"type_in":["regular_bearish"]},"member":"rsi_div_4h"},{"events":{"type_in":["regular_bearish"]},"member":"macd_div_4h"}]},{"events":{"direction":"bearish","kind_in":["CHoCH"],"within_candles":20},"member":"breaks_4h"},{"field":"resistance.0.distance_atr","lte":1.0,"member":"zones_1d"}]}}],"lineage_version":2,"members":[{"category":"divergence","key":"rsi_div_4h","label":"4-hour RSI divergence","ref":{"id":"ta.divergence.rsi","params":{"active_bars":30,"left":5,"lookback":150,"max_gap":60,"min_gap":5,"right":5},"timeframe":"4h","version":1},"role":"condition"},{"category":"divergence","key":"macd_div_4h","label":"4-hour MACD divergence","ref":{"id":"ta.divergence.macd","params":{"active_bars":30,"left":5,"line":"histogram","lookback":150,"max_gap":60,"min_gap":5,"right":5},"timeframe":"4h","version":1},"role":"condition"},{"category":"structure","key":"breaks_4h","label":"4-hour structure breaks","ref":{"id":"structure.breaks","params":{"left":5,"lookback":150,"right":5},"timeframe":"4h","version":1},"role":"condition"},{"category":"levels","key":"zones_1d","label":"Daily support and resistance","ref":{"id":"levels.zones","params":{"left":5,"lookback":300,"max_width_mult":2.0,"min_touches":2,"per_side":3,"right":5,"width_atr":0.5},"timeframe":"1D","version":1},"role":"levels"},{"category":"volume","key":"cmf_4h","label":"4-hour Chaikin Money Flow","ref":{"id":"volume.cmf","params":{"length":20},"timeframe":"4h","version":1},"role":"context"}],"name":"Reversal Evidence","notes":"No score: events and price levels do not average meaningfully. RSI and MACD divergences come from the same price swings, so they form one compound item with any(); the three items have disjoint support sets and so count as three clusters under count_at_least. Divergence, CHoCH and zones all derive from price: the rule is corroboration, not independent confirmation, and count_distinct_sources_at_least: 2 would be refused as unsatisfiable. Only active confirmed divergences count (developing, expired and invalidated do not). About half of divergences break their invalidation level within 30 candles on development data; this Group reports evidence, not a trade. If the zone signal is unavailable or no zone exists on that side, its predicate is unknown, so the setup can be unknown rather than not met.","question":"Is there corroborating evidence that the current move may be turning, and where?","schema":"angstrom.group/1","score":null}$json$::jsonb);
select public.analysis_seed_starter('starter:trend', $json${"conditions":[],"lineage_version":3,"members":[{"category":"trend","key":"moving_averages","label":"Moving averages (50, 200 days)","ref":{"id":"ma.position","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"trend","key":"ichimoku","label":"Ichimoku cloud","ref":{"id":"ichimoku.position","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"trend","key":"macd","label":"MACD line","ref":{"id":"macd.level","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"}],"name":"Trend","purpose":"The dashboard's Trend reading rebuilt from its 3 parts: the average of their standard scores, so the same input data gives the same number. Copy it to change parts or weights.","question":"Is price above or below its 50- and 200-day levels, and by how much?","schema":"angstrom.group/1","score":{"meaning":"Trend (weeks to months): Is price above or below its 50- and 200-day levels, and by how much? -1..+1 (shown as -100..+100); positive means up. The same calculation as the dashboard's reading; a description, not a forecast.","method":"weighted_mean","min_coverage":{"den":3,"num":1},"range":[-1,1]}}$json$::jsonb);
select public.analysis_seed_starter('starter:stretch', $json${"conditions":[],"lineage_version":3,"members":[{"category":"stretch","key":"rsi","label":"RSI (14)","ref":{"id":"rsi.level","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"stretch","key":"stochastic","label":"Stochastic (14, 3)","ref":{"id":"stochastic.level","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"stretch","key":"bollinger","label":"Bollinger position (20, 2)","ref":{"id":"bollinger.position","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"stretch","key":"momentum","label":"7-day move","ref":{"id":"move.seven_day","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"stretch","key":"macd_acceleration","label":"MACD histogram","ref":{"id":"macd.acceleration","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"}],"name":"Stretch","purpose":"The dashboard's Stretch reading rebuilt from its 5 parts: the average of their standard scores, so the same input data gives the same number. Copy it to change parts or weights.","question":"How far has price run up or down lately, within its recent range?","schema":"angstrom.group/1","score":{"meaning":"Stretch (1 to 4 weeks): How far has price run up or down lately, within its recent range? -1..+1 (shown as -100..+100); positive means up. The same calculation as the dashboard's reading; a description, not a forecast.","method":"weighted_mean","min_coverage":{"den":5,"num":1},"range":[-1,1]}}$json$::jsonb);
select public.analysis_seed_starter('starter:flow', $json${"conditions":[],"lineage_version":3,"members":[{"category":"flow","key":"obv","label":"On-balance volume","ref":{"id":"obv.balance","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"},{"category":"flow","key":"heavy_volume","label":"Heavy-volume candle","ref":{"id":"volume.heavy_candle","params":{},"timeframe":"1D","version":1},"role":"score","transform":{"field":"standard_score","high":1,"kind":"clip","low":-1,"version":1},"weight":1,"when_unavailable":"exclude"}],"name":"Flow","purpose":"The dashboard's Flow reading rebuilt from its 2 parts: the average of their standard scores, so the same input data gives the same number. Copy it to change parts or weights.","question":"Is trading volume backing rises or falls?","schema":"angstrom.group/1","score":{"meaning":"Flow (days to weeks): Is trading volume backing rises or falls? -1..+1 (shown as -100..+100); positive means up. The same calculation as the dashboard's reading; a description, not a forecast.","method":"weighted_mean","min_coverage":{"den":2,"num":1},"range":[-1,1]}}$json$::jsonb);

-- Keep each starter's listed name in step with its newest version.
update public.analysis_configs c set name = v.body ->> 'name'
  from public.analysis_config_versions v
 where c.starter_alias is not null and v.config_id = c.id and v.version = c.current_version
   and c.name is distinct from v.body ->> 'name';
